sys_script_include.script:
var CancelTaskHelper = Class.create();
CancelTaskHelper.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    cancelTaskAndNotify: function() {
        var sys_id = this.getParameter('sysparm_sys_id');
        var gr = new GlideRecord('x_1790229_event_ma_event_task'); // Or replace with your specific task table
        if (gr.get(sys_id)) {
            gr.setValue('u_status', 'cancelled'); // or use 'status' if it's a custom field
            gr.update();

            // Trigger email notification (Example - use your own notification logic)
            gs.eventQueue('x_1790229_event_ma.notify.cancellation', gr, gr.assigned_to, gs.getUserID());
        }
        return 'Task Cancelled and user notified';
    },


    type: 'CancelTaskHelper'
});
